cd /private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/a0634569-ed21-4a52-842e-6a4f8f049227; cat > tests/zz-tmp-rename.test.ts <<'EOF'
import { afterAll, beforeAll, expect, it, vi } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { InvalidSlugError } from "@/lib/slug";
import * as orgService from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { listActivity } from "@/server/services/activity-service";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => { vi.useRealTimers(); cleanup(); });

it("renames", async () => {
  const a = await createTenant("alpha");
  const b = await createTenant("beta");
  const seen: unknown[] = [];
  const off = subscribe("organization.slug_changed", (p) => { seen.push(p); });
  vi.useFakeTimers({ toFake: ["Date"] });
  const t0 = new Date("2026-01-01T00:00:00.000Z");
  vi.setSystemTime(t0);
  const r = await orgService.renameOrganizationSlug(a.actors.admin, { orgId: a.org.id, slug: "alpha-new" });
  expect(r.slug).toBe("alpha-new");
  expect(r.name).toBe(a.org.name);
  expect(seen).toHaveLength(1);
  expect((await orgService.resolveOrgBySlug("alpha"))?.id).toBe(a.org.id);
  expect(await resolveActorForOrg({ userId: a.userIds.owner, email: "", activeOrgId: null, expiresAt: "x" as never }, "alpha")).not.toBeNull();
  await expect(orgService.renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "alpha" })).rejects.toBeInstanceOf(InvalidSlugError);
  await expect(orgService.renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "alpha-new" })).rejects.toBeInstanceOf(InvalidSlugError);
  await expect(orgService.renameOrganizationSlug(a.actors.member, { orgId: a.org.id, slug: "zzz" })).rejects.toThrow();
  const c = await orgService.createOrganization(b.userIds.owner, { name: "x", slug: "alpha", plan: "free" });
  expect(c.slug).toBe("alpha-2");
  await orgService.renameOrganizationSlug(a.actors.owner, { orgId: a.org.id, slug: "alpha-new" });
  expect(seen).toHaveLength(1);
  vi.setSystemTime(new Date(t0.getTime() + 30 * 86400000 - 1));
  expect((await orgService.resolveOrgBySlug("alpha"))?.id).toBe(a.org.id);
  vi.setSystemTime(new Date(t0.getTime() + 30 * 86400000));
  expect(await orgService.resolveOrgBySlug("alpha")).toBeNull();
  const r2 = await orgService.renameOrganizationSlug(b.actors.owner, { orgId: b.org.id, slug: "alpha" });
  expect(r2.slug).toBe("alpha");
  const page = await listActivity(a.actors.owner, { orgId: a.org.id, action: ["organization.slug_changed"], limit: 25, cursor: null });
  expect(page.items).toHaveLength(1);
  expect(page.items[0]?.metadata).toEqual({ from: "alpha", to: "alpha-new" });
  off();
});
EOF
npx vitest run tests/zz-tmp-rename.test.ts 2>&1 | grep -v "npm warn" | tail -30; rm tests/zz-tmp-rename.test.ts

